export const STAGE_IDS: string[] = ["n-gate", "n-verify", "n-gross", "n-qfs", "n-unload", "n-tare", "n-netwt", "n-lot", "n-bin", "n-grn", "n-stock", "n-drying", "n-otheract", "n-ledger", "n-xferdec", "n-reject"];

/** label -> col for one stage. Throws on an unknown label so a typo can't silently no-op a write. */
export function colFor(stageId: string, label: string): string {
  const spec = STAGE_FIELD_MAP[stageId];
  if (!spec) throw new Error(`Unknown stage "${stageId}"`);
  const f = spec.fields.find((x) => x.label === label);
  if (!f) throw new Error(`Unknown field "${label}" on stage "${stageId}"`);
  return f.col;
}

